/* Material autoral. Fontes oficiais consultadas em 15/10/2026. */
window.LEGISLACAO = (() => {
  const PA = {title:'ALEPA — Constituição estadual, atualização maio/2026',url:'https://www.alepa.pa.gov.br/Servicos/Download?Id=28'};
  const RI = {title:'ALEPA — Regimento Interno, Resolução 02/2022',url:'https://www.alepa.pa.gov.br/Servicos/Download?Id=1'};
  const LEIS = {title:'ALEPA — Banco de Leis e atos normativos',url:'https://bancodeleis.alepa.pa.gov.br/'};
  const VIDEO = {title:'TV Senado — como a lei é feita (vídeo introdutório; regras federais)',url:'https://www12.senado.leg.br/noticias/videos/2024/08/como-a-lei-e-feita-no-brasil-exposicao-no-senado-mostra-o-processo-legislativo'};
  const S = (title,body)=>({title,body});
  // Entrada: enunciado, resposta correta, quatro distratores, explicação.
  const Q = (rows)=>rows.map((r,i)=>{const options=r.slice(1,6); const answer=i%5; const correct=options.shift();options.splice(answer,0,correct);return {prompt:r[0],options,answer,explanation:r[6]};});
  const L=(id,title,edital,sections,rows,sources,videos=[])=>({id,subject:'Legislação e ética',title,edital,sections,questions:Q(rows),sources,videos,realQuestions:[]});
  return [
    L('leg-etica','Ética pública, cidadania e prevenção do assédio','Ética e moral; princípios, valores e lei; democracia e cidadania; conduta e ética profissional; responsabilidade social; função pública; enfrentamento ao assédio moral e sexual.',[
      S('Ética, moral e legalidade','<p><strong>Moral</strong> é o conjunto de valores, costumes e normas de conduta de uma comunidade. <strong>Ética</strong> é a reflexão crítica sobre esses valores e sobre as razões de uma ação. Não se limita a obedecer ordens ou à conveniência pessoal. A lei estabelece deveres exigíveis; a avaliação ética também considera finalidade, justiça, respeito e consequências. Algo socialmente tolerado pode ser ilegal, e uma brecha normativa não torna automaticamente íntegra uma conduta.</p><p>No serviço público, legalidade, impessoalidade, moralidade, publicidade e eficiência orientam a atuação. Eficiência exige bons resultados com uso responsável de recursos e não autoriza afastar a lei. Impessoalidade rejeita favoritismo, perseguição e promoção pessoal. Publicidade permite controle, preservando os sigilos legalmente protegidos. Moralidade administrativa exige honestidade, boa-fé e finalidade pública.</p>'),
      S('Decisões concretas de um servidor','<p>Ao receber pedido de um conhecido para adiantar atendimento, aplique critérios objetivos e a mesma ordem usada para todos. Ao identificar interesse pessoal numa decisão, comunique a situação e siga o procedimento de impedimento ou afastamento pertinente. Não use dados internos para vantagem privada. Recusar vantagens indevidas, registrar decisões, prestar contas e tratar usuários com respeito são práticas de integridade.</p><p>Democracia não se reduz ao voto: envolve acesso à informação, participação em audiências, fiscalização social e possibilidade de contestação. Responsabilidade social inclui acessibilidade, inclusão, sustentabilidade e atenção aos impactos do serviço sobre grupos vulneráveis. Uma interface pública inacessível pode impedir o exercício de direitos mesmo quando tecnicamente funciona.</p>'),
      S('Reconhecer, prevenir e enfrentar assédio','<p>Assédio moral envolve práticas abusivas de humilhação e degradação do ambiente de trabalho; reiteração e contexto são relevantes na sua caracterização. Cobrança objetiva, respeitosa e proporcional de tarefas não se confunde com humilhação. Uma agressão isolada também exige resposta, mesmo que não receba a classificação de assédio moral. O abuso pode ocorrer entre colegas, de chefias para subordinados ou no sentido inverso.</p><p>Condutas sexuais indesejadas podem ser graves mesmo sem repetição. A noção administrativa é mais ampla que o tipo penal do art. 216-A do Código Penal, que exige os elementos legais de superioridade hierárquica ou ascendência. Não confunda toda conduta inadequada com esse crime específico.</p><p>A prevenção combina formação, canais acessíveis, gestão respeitosa e proteção contra retaliação. No acolhimento, preserve privacidade e provas, evite culpabilização e encaminhe aos canais institucionais competentes. A apuração deve observar contraditório, ampla defesa e imparcialidade. Materiais federais da CGU são referência conceitual; não transformam automaticamente procedimentos federais em regras da ALEPA.</p>')
    ],[
      ['Um servidor prioriza amigos sem critério legal. Qual princípio é diretamente comprometido?','Impessoalidade','Continuidade','Especialidade','Autotutela','Hierarquia','Impessoalidade exige critérios objetivos; amizade não fundamenta preferência administrativa. Os demais conceitos não legitimam o favorecimento.'],
      ['A relação entre ética e moral é melhor descrita por:','Ética reflete criticamente sobre valores e condutas morais','Ética é mera repetição de costumes','Moral equivale exclusivamente à lei penal','Ética só existe na vida privada','Toda moral é universal e imutável','A ética examina justificativas da ação. Costumes variam e não substituem o julgamento crítico nem as obrigações jurídicas.'],
      ['Para cumprir prazo, uma chefia propõe ignorar requisito legal. A eficiência:','Deve ser buscada dentro da legalidade','Revoga a legalidade','Autoriza qualquer meio','Dispensa motivação','É incompatível com controle','Eficiência integra os princípios administrativos e não afasta os demais. A meta não valida um meio ilegal.'],
      ['Uma conduta sexual indesejada ocorreu uma única vez. É correto:','A ausência de repetição não exclui sua gravidade ou apuração','Nunca pode ser apurada','Só interessa se houver testemunha presencial','É sempre consentida','Só existe abuso entre pessoas de sexos diferentes','Repetição não é condição geral para apurar violência sexual. Contexto, consentimento e elementos legais precisam ser examinados.'],
      ['É medida adequada de enfrentamento ao assédio:','Acolher e prevenir retaliação, preservando a apuração imparcial','Divulgar a identidade da vítima','Punir sem procedimento','Exigir confronto público','Ignorar denúncia contra chefia','Proteção e acolhimento coexistem com devido processo. Exposição, retaliação e punição automática prejudicam direitos.'],
      ['Qual situação, isoladamente, constitui gestão regular?','Cobrança respeitosa e proporcional de uma tarefa','Humilhação pública recorrente','Isolamento deliberado punitivo','Ameaça sexual para promoção','Insultos discriminatórios','Cobrar entrega com respeito faz parte da gestão. As outras situações envolvem abuso ou discriminação.'],
      ['Um programador identifica interesse pessoal na escolha de fornecedor. Deve:','Comunicar o conflito e seguir as regras de impedimento aplicáveis','Omitir o vínculo','Apagar os registros','Escolher o fornecedor por amizade','Decidir secretamente','Transparência e tratamento formal do conflito protegem a decisão pública. Interesse particular não pode dirigir o procedimento.'],
      ['A cidadania democrática também se exerce mediante:','Participação e controle social','Somente votação eleitoral','Obediência sem crítica','Sigilo irrestrito de gastos','Exclusão de minorias','Cidadania envolve participar, acompanhar e questionar decisões públicas, além de escolher representantes.'],
      ['Qual conduta concretiza responsabilidade social num sistema público?','Garantir acessibilidade aos serviços digitais','Exigir recursos inacessíveis sem alternativa','Usar dados para benefício privado','Ocultar critérios de atendimento','Priorizar usuários influentes','Acessibilidade reduz barreiras ao exercício de direitos. Eficiência técnica sem inclusão não basta.'],
      ['O conceito administrativo de conduta sexual abusiva e o crime do art.216-A:','Não são automaticamente equivalentes; o tipo penal exige elementos próprios','São sempre idênticos','Dependem sempre de repetição anual','Só alcançam empresas privadas','Dispensam análise do contexto','O enquadramento criminal é estrito. A instituição pode prevenir e apurar condutas inadequadas que não preencham aquele tipo penal específico.']
    ],[{title:'CGU — Guia Lilás de prevenção e enfrentamento ao assédio',url:'https://repositorio.cgu.gov.br/bitstream/1/94045/1/Guia_Prevencao_Assedio_2024.pdf'},{title:'Constituição Federal — art.37',url:'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'}]),
    L('leg-lgpd','LGPD e segurança da informação no serviço público','Lei 13.709/2018 e alterações; fundamentos, conceitos e mecanismos de segurança da informação.',[
      S('O que a LGPD protege','<p>A LGPD protege dados relativos a pessoa natural identificada ou identificável, em suporte digital ou físico. Nome, matrícula e identificação indireta podem ser dados pessoais. Dados sensíveis incluem origem racial ou étnica, convicção religiosa, opinião política, filiação sindical ou a organização religiosa, filosófica ou política, saúde, vida sexual e dados genéticos ou biométricos vinculados a pessoa natural. Dados anonimizados deixam de ser pessoais nas condições do art.12; substituir nome por código reversível geralmente produz pseudonimização, não anonimização definitiva.</p><p>Tratamento inclui coletar, acessar, organizar, compartilhar, armazenar e eliminar. O controlador decide sobre o tratamento; o operador o realiza em nome do controlador; o encarregado atua como canal de comunicação conforme a lei. A pessoa a quem os dados se referem é o titular. A ANPD regula e fiscaliza dentro das competências legais.</p>'),
      S('Bases legais e princípios','<p>Consentimento é uma das bases legais, não a única. O art.7º inclui obrigação legal ou regulatória, políticas públicas, pesquisa, execução contratual, exercício regular de direitos, proteção da vida, tutela da saúde nas condições legais, legítimo interesse e proteção do crédito. Dados sensíveis seguem o art.11: não basta transportar automaticamente uma base do art.7º. Crianças e adolescentes exigem observância do melhor interesse.</p><p>Finalidade delimita o propósito; adequação exige compatibilidade; necessidade restringe a coleta ao mínimo pertinente. Livre acesso, qualidade, transparência, segurança, prevenção, não discriminação e responsabilização completam os princípios. No Poder Público, o tratamento deve atender finalidade pública e competências legais, com informação clara sobre hipóteses, procedimentos e práticas. Não se deve exigir consentimento artificial para uma obrigação legal nem usar o poder público para finalidade privada.</p>'),
      S('Direitos e proteção desde o projeto','<p>O titular pode solicitar confirmação, acesso, correção, informações sobre compartilhamento e outros direitos do art.18. Eliminação não é absoluta: há hipóteses legais de conservação. Compartilhar dados entre órgãos também exige finalidade, base e controles. Incidentes relevantes precisam ser avaliados e comunicados conforme lei e regulamentação aplicável; não presuma que qualquer incidente gere automaticamente multa.</p><p>Confidencialidade restringe acesso; integridade protege contra alteração indevida; disponibilidade mantém acesso autorizado quando necessário. Autenticação verifica identidade, autorização determina permissões, auditoria registra ações. Aplique menor privilégio, autenticação multifator, criptografia, atualização, segmentação e backups testados. Hash não é criptografia reversível, e backup não substitui controle de acesso. No desenvolvimento, use dados sintéticos em testes, minimize logs pessoais, defina retenção e documente o fluxo dos dados antes da implantação.</p>')
    ],[
      ['Uma matrícula permite identificar o servidor com uma tabela auxiliar. Trata-se de:','Dado pessoal','Dado necessariamente anônimo','Dado apenas de pessoa jurídica','Informação fora da LGPD','Dado público sem proteção','Identificação indireta basta para caracterizar dado pessoal. A existência de uma tabela de associação afasta a alegação automática de anonimização.'],
      ['Qual é dado pessoal sensível?','Informação sobre saúde de pessoa identificada','Número de protocolo sem pessoa identificável','Preço de um computador','Nome de uma cidade','CNPJ isolado','Saúde vinculada à pessoa natural integra o rol de dados sensíveis. Os outros exemplos, como apresentados, não possuem essa natureza.'],
      ['O controlador é quem:','Toma decisões referentes ao tratamento','Sempre hospeda o banco de dados','É necessariamente o titular','É qualquer visitante do site','Substitui o Poder Judiciário','Controlador decide finalidades e elementos do tratamento; operador executa em seu nome. Hospedagem não define sozinha o papel.'],
      ['Um órgão trata dados para cumprir obrigação legal. O consentimento:','Não é a única base legal possível','É obrigatório em toda operação','Deve ser obtido por silêncio','Afasta todos os direitos','Autoriza coleta ilimitada','A LGPD prevê múltiplas bases. A obrigação legal pode fundamentar tratamento sem depender de consentimento, mantendo princípios e direitos.'],
      ['Coletar apenas dados pertinentes ao serviço concretiza:','Necessidade','Publicidade irrestrita','Irresponsabilidade','Indisponibilidade','Revogação','Necessidade limita o tratamento ao mínimo adequado ao propósito. Não se confunde com coletar tudo por eventual utilidade futura.'],
      ['Substituir nomes por códigos, mantendo a chave de associação, é:','Pseudonimização, sem anonimização automática','Destruição completa dos dados','Eliminação de todas as obrigações','Consentimento implícito','Proibição de uso de criptografia','Se há meios de reidentificação, o dado permanece protegido. A chave deve receber controles próprios.'],
      ['Qual propriedade é afetada pela alteração indevida de um parecer?','Integridade','Portabilidade','Elasticidade','Compressão','Interoperabilidade','Integridade refere-se à preservação contra modificação indevida. Confidencialidade trata de acesso e disponibilidade de acesso oportuno.'],
      ['Após autenticar um usuário, verificar se pode excluir um processo é:','Autorização','Anonimização','Compactação','Indexação','Assinatura da lei','Autenticação identifica; autorização define ações permitidas. Login válido não concede acesso irrestrito.'],
      ['Uma solicitação de eliminação deve considerar:','As hipóteses legais de conservação dos dados','Exclusão irrestrita de todo documento público','Somente vontade do operador','Proibição de responder ao titular','Impossibilidade de corrigir dados','Direitos devem ser atendidos de acordo com a lei; obrigação legal e outras hipóteses do art.16 podem justificar conservação.'],
      ['Uma boa prática em ambiente de desenvolvimento é:','Usar dados sintéticos e acesso restrito','Copiar base real para computador pessoal','Publicar senhas no repositório','Compartilhar conta administrativa','Desativar logs sem critério','Dados sintéticos reduzem exposição. Os demais comportamentos ampliam riscos de vazamento e comprometem responsabilização.']
    ],[{title:'LGPD — texto compilado oficial',url:'https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm'},{title:'CERT.br — Cartilha de Segurança',url:'https://cartilha.cert.br/'}],[{title:'ANPD — palestra LGPD no setor público (página com vídeo)',url:'https://www.gov.br/anpd/pt-br/assuntos/noticias/palestra-201clgpd-no-setor-publico201d'}]),
    L('leg-anticorrupcao','Lei Anticorrupção e programas de integridade','Lei 12.846/2013; Decreto 11.129/2022.',[
      S('Responsabilização da pessoa jurídica','<p>A Lei 12.846/2013 estabelece responsabilidade objetiva administrativa e civil de pessoas jurídicas por atos lesivos à administração pública nacional ou estrangeira praticados em seu interesse ou benefício, exclusivo ou não. Objetiva significa que não depende de provar culpa da empresa, mas continuam necessários os elementos legais do ato e sua vinculação. Isso não cria responsabilidade penal automática da pessoa jurídica nem elimina a responsabilidade individual de dirigentes e demais envolvidos, examinada segundo sua culpabilidade.</p><p>Os atos lesivos abrangem oferecer vantagem indevida a agente público ou pessoa relacionada, financiar ilícitos, usar interposta pessoa para ocultar interesses, fraudar licitações e contratos e dificultar investigação ou fiscalização. Uma vantagem oferecida já pode configurar a hipótese legal; não é necessário que o agente aceite em todos os casos.</p>'),
      S('Sanções e processo','<p>Na esfera administrativa, a lei prevê multa e publicação extraordinária da decisão condenatória. A multa segue critérios legais, de 0,1% a 20% do faturamento bruto do exercício anterior à instauração do processo administrativo, excluídos tributos, nunca inferior à vantagem auferida quando estimável. Se o critério do faturamento não puder ser utilizado, a lei prevê faixa própria em reais. Reparação integral do dano não é dispensada pelas sanções. Na via judicial, há sanções específicas, incluindo perdimento de bens e restrições ou dissolução nas hipóteses legais.</p><p>O processo administrativo de responsabilização assegura defesa e contraditório. A autoridade competente, a comissão e os atos processuais obedecem à lei e à regulamentação. O Decreto 11.129/2022 regulamenta a lei e detalha, no âmbito próprio, investigação preliminar, processo, cálculo da multa, leniência e integridade. Não se deve importar automaticamente a competência da CGU para todo procedimento estadual.</p>'),
      S('Leniência e integridade efetiva','<p>Leniência é acordo de colaboração sujeito a requisitos; não representa imunidade geral. A colaboração deve contribuir efetivamente para a identificação dos envolvidos e obtenção de informações e provas, nos termos aplicáveis. A reparação integral continua devida. Benefícios dependem do cumprimento do acordo.</p><p>Um programa de integridade reúne prevenção, detecção e remediação. Comprometimento da direção, avaliação periódica de riscos, código de conduta, treinamento, canal de denúncias, proteção contra retaliação, controles internos, registros contábeis, diligência de terceiros e monitoramento são elementos relevantes. Um código que ninguém aplica não demonstra efetividade. Para uma contratação de software, examine intermediários, acesso a agentes públicos, pagamentos atípicos, critérios de aceitação e rastreabilidade das decisões.</p>')
    ],[
      ['A responsabilidade da pessoa jurídica na Lei 12.846 é:','Objetiva, administrativa e civil','Somente penal','Sempre dependente de dolo de cada sócio','Exclusivamente disciplinar','Limitada a empresas públicas','O art.2º prevê responsabilização objetiva administrativa e civil por atos no interesse ou benefício da pessoa jurídica.'],
      ['A lei alcança atos contra:','Administração pública nacional ou estrangeira','Somente a União','Somente municípios','Somente empresas privadas','Apenas o Poder Executivo federal','O alcance legal inclui administração nacional e estrangeira. Limitar a um ente ou poder altera indevidamente a regra.'],
      ['A sanção administrativa prevista expressamente é:','Publicação extraordinária da decisão condenatória','Prisão da empresa','Pena de morte empresarial','Cassação automática de cidadania','Suspensão automática de todo contrato privado','Multa e publicação extraordinária são sanções administrativas da lei. As demais opções não correspondem a esse rol.'],
      ['A responsabilidade objetiva dispensa:','Prova de culpa da pessoa jurídica, sem dispensar os demais elementos legais','Prova do ato lesivo','Vínculo com interesse ou benefício','Processo administrativo','Direito de defesa','Objetividade afasta a exigência de culpa, não a demonstração do ato, do vínculo nem as garantias processuais.'],
      ['O pagamento de multa:','Não afasta a reparação integral do dano','Substitui necessariamente a reparação','Exclui todos os processos','Elimina fatos do registro','Impede qualquer fiscalização','A sanção e o ressarcimento têm funções distintas; o dever de reparar permanece.'],
      ['Qual conduta está entre os atos lesivos?','Dificultar investigação de órgão público','Apresentar documentos verdadeiros','Recusar propina','Treinar empregados','Adotar auditoria independente','Obstruir fiscalização integra as hipóteses legais. Medidas de transparência e prevenção não constituem por si atos lesivos.'],
      ['O acordo de leniência é:','Instrumento condicionado de colaboração','Perdão automático sem requisitos','Contrato para ocultar provas','Dispensa irrestrita de ressarcimento','Substituto de qualquer controle','Acordo e benefícios dependem dos pressupostos legais e da colaboração efetiva; não há imunidade total.'],
      ['A avaliação de integridade deve priorizar:','Aplicação efetiva dos mecanismos no contexto de risco','Quantidade de páginas do código','Ausência de registros','Publicidade sem controles','Extinção de canais de denúncia','Efetividade e adequação aos riscos importam. Documentos formais sem prática não bastam.'],
      ['A responsabilização da empresa:','Não exclui a individual dos envolvidos','Absorve todo crime individual','Exige condenação prévia de todos os sócios','Só ocorre com dissolução','Impede defesa de dirigentes','A lei mantém responsabilidade individual segundo culpabilidade e permite responsabilizar a pessoa jurídica independentemente.'],
      ['Na contratação de terceiro, é prática de integridade:','Realizar diligência proporcional aos riscos','Ignorar beneficiário final','Pagar comissões sem justificativa','Eliminar registros de reunião','Aceitar qualquer intermediário','Diligência de terceiros identifica riscos de intermediação indevida e favorece controles compatíveis com a operação.']
    ],[{title:'Lei 12.846/2013 — Planalto',url:'https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2013/lei/l12846.htm'},{title:'Decreto 11.129/2022 — Planalto',url:'https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2022/decreto/d11129.htm'}]),
    L('leg-improbidade','Improbidade administrativa após a Lei 14.230/2021','Lei 8.429/1992 e alterações, especialmente Lei 14.230/2021.',[
      S('Ilegalidade não equivale automaticamente a improbidade','<p>A improbidade integra o direito administrativo sancionador. A redação reformada da Lei 8.429 exige condutas dolosas tipificadas nos arts.9º, 10 e 11. Dolo não se confunde com simples voluntariedade: exige vontade livre e consciente de alcançar o resultado ilícito tipificado. Erro administrativo, divergência interpretativa ou falha operacional não autorizam, por si, condenação por improbidade. Podem existir outras responsabilidades, mas o enquadramento depende de seus próprios requisitos.</p><p>Agente público tem conceito amplo, inclusive quem exerce transitoriamente ou sem remuneração mandato, cargo, emprego ou função. Particular pode responder se induzir ou concorrer dolosamente para o ato; o simples vínculo com uma empresa não transfere automaticamente a responsabilidade a todos os seus integrantes.</p>'),
      S('Três grupos de atos','<p><strong>Art.9º:</strong> enriquecimento ilícito, como receber vantagem patrimonial indevida em razão da função. <strong>Art.10:</strong> lesão ao erário, com perda patrimonial efetiva e comprovada e os demais elementos legais; não basta dano presumido. <strong>Art.11:</strong> violação dolosa dos deveres e princípios nas condutas legalmente tipificadas. Evite a fórmula antiga de transformar qualquer ofensa abstrata a princípio em improbidade.</p><p>Exemplo: receber propina para liberar medição aproxima-se do art.9º; liberar conscientemente pagamento por serviço inexistente, causando perda efetiva, exige exame do art.10. O mesmo fato não autoriza somar sanções mecanicamente: tipificação, proporcionalidade e vedação de duplicidade devem ser observadas.</p>'),
      S('Consequências e leitura da lei atual','<p>As sanções variam segundo a categoria: perda dos bens acrescidos ilicitamente, perda da função, suspensão de direitos políticos, multa civil e proibição de contratar ou receber benefícios, conforme o caso. O art.12 estabelece limites diferentes: nos arts.9º e 10, suspensão de direitos políticos e proibição de contratar podem chegar, respectivamente, a 14 e 12 anos; no art.11, a lei prevê multa de até 24 remunerações e proibição por até 4 anos, sem reproduzir todo o conjunto das outras categorias. Aplicação não é automática: depende da decisão e dos critérios legais.</p><p>O ressarcimento corresponde ao dano efetivo e possui análise própria. Prescrição, retroatividade e legitimidade processual têm decisões do STF relevantes: leia as notas de controle de constitucionalidade do texto oficial e não use apostila anterior à reforma como se vigente fosse. Para a prova, separe texto legal atual, jurisprudência expressamente exigida e data do fato. Declaração de bens, comunicação de irregularidades e documentação de decisões ajudam a prevenção, mas não substituem o devido processo.</p>')
    ],[
      ['Na redação reformada, os atos dos arts.9º,10 e 11 exigem:','Dolo nos termos legais','Sempre somente culpa leve','Mero resultado insatisfatório','Apenas reclamação de cidadão','Exclusivamente dano presumido','A Lei 14.230 alterou o regime para exigir condutas dolosas tipificadas. Não basta a voluntariedade genérica.'],
      ['Receber vantagem patrimonial indevida em razão da função corresponde, em tese, ao grupo de:','Enriquecimento ilícito','Responsabilidade sem conduta','Erro escusável','Anulação eleitoral','Direito adquirido','O art.9º concentra atos de enriquecimento ilícito, observados dolo e demais requisitos.'],
      ['O art.10 requer quanto ao patrimônio público:','Lesão efetiva e comprovada','Dano sempre presumido','Apenas risco abstrato','Vantagem privada obrigatória em qualquer caso','Desaprovação política','A redação legal exige perda patrimonial efetiva e comprovada; risco ou presunção não a substituem.'],
      ['Uma falha operacional isolada caracteriza automaticamente improbidade?','Não; é necessária tipificação e demonstração dos requisitos','Sim, qualquer erro basta','Sim, mesmo sem agente','Sim, se repercutir na imprensa','Sim, porque dolo é dispensável','Ilegalidade e improbidade não são sinônimos; outras consequências podem existir sem preencher a Lei 8.429.'],
      ['O particular pode responder quando:','Induz ou concorre dolosamente para o ato','É parente de qualquer servidor','É empregado sem participação','Apenas apresenta proposta regular','Possui patrimônio alto','Participação dolosa deve ser demonstrada. Relação pessoal ou empresarial, isoladamente, não basta.'],
      ['O art.11 deve ser estudado como:','Conjunto de condutas tipificadas, com requisitos legais','Cláusula ilimitada para punir toda discordância','Norma exclusivamente penal','Autorização para dispensar dolo','Lista de crimes eleitorais','Após a reforma, não se deve enquadrar qualquer conduta somente por invocar genericamente um princípio.'],
      ['A aplicação das sanções deve observar:','Proporcionalidade e critérios legais','Sempre o máximo abstrato','Punição coletiva sem individualização','Ausência de contraditório','Preferência política','A gravidade concreta e os parâmetros legais orientam a decisão. Punição automática ou coletiva não atende ao regime.'],
      ['Agente público para essa lei inclui:','Pessoa que exerce função transitoriamente e sem remuneração','Somente servidor estável','Somente parlamentar','Apenas ocupante de cargo efetivo','Apenas empregado celetista','O conceito legal é amplo e abrange várias formas de investidura e exercício.'],
      ['No regime do art.11, a multa civil prevista pode alcançar:','24 vezes o valor da remuneração percebida pelo agente','Sempre 100 salários mínimos','Qualquer valor sem limite','Apenas um real','Exatamente o valor de todos os contratos','O art.12, III, prevê teto de 24 remunerações, sujeito aos critérios legais; não se importam automaticamente penas de outros incisos.'],
      ['Para estudar retroatividade e prescrição, é adequado:','Conferir lei atual e decisões vinculantes pertinentes','Usar exclusivamente texto de 1992','Supor retroatividade irrestrita','Desconsiderar data dos fatos','Presumir que toda pretensão é imprescritível','A reforma e a interpretação constitucional exigem atenção a situações distintas. Generalizações apagam requisitos e limites.']
    ],[{title:'Lei 8.429/1992 — texto compilado e notas de decisões',url:'https://www.planalto.gov.br/ccivil_03/leis/l8429compilada.htm'}],[{title:'TV Justiça — Saber Direito: Lei de Improbidade Administrativa, aula 1 (2022)',url:'https://www.youtube.com/watch?v=o-5sq1Ff7hs'}]),
    L('leg-constituicao-pa','Constituição do Pará: poderes, deputados e controle','Constituição do Pará: arts.11,86,90,92 a 116,121,161,162,168 e 341. Processo legislativo complementado na próxima aula.',[
      S('Organização e autonomia','<p>O art.11 estabelece Legislativo, Executivo e Judiciário independentes e harmônicos; a independência não elimina fiscalização recíproca. O art.86 atribui o Legislativo à Assembleia, com autonomia administrativa e financeira. A proposta orçamentária deve observar limites da LDO e ser encaminhada pelo Presidente após aprovação do Plenário. Legislatura dura quatro anos; não confunda com sessão legislativa anual nem com cada reunião parlamentar.</p><p>O art.90 trata da representação judicial do Poder Legislativo pela Procuradoria, sem prejuízo das atribuições da PGE, e do assessoramento técnico. O art.92 reúne competências exclusivas, como organização interna, fiscalização e decisões político-institucionais; diferencie-as das matérias legisladas com sanção. O art.93 disciplina convocação de autoridades e pedidos de informação, mecanismos de controle que não equivalem a subordinação entre poderes.</p>'),
      S('Deputados, reuniões e comissões: roteiro de leitura','<p>Nos arts.94 a 99, associe imunidades, incompatibilidades, perda do mandato, licenças e suplência. Imunidade material protege opiniões, palavras e votos nos limites constitucionais; não é autorização geral para qualquer ilícito. Incompatibilidades impedem determinados vínculos e negócios; perda do mandato tem hipóteses e procedimentos próprios. Não confunda decisão política de perda com declaração pela Mesa nem presuma que qualquer afastamento gera perda definitiva.</p><p>Os arts.100 e 101 tratam das reuniões e comissões. Comissões permanentes acompanham áreas temáticas; temporárias têm finalidade delimitada. CPI exige fato determinado e prazo certo e possui poderes de investigação nos limites constitucionais, sem se transformar em órgão judicial de condenação. Os arts.102 a 111 estruturam espécies normativas, emendas, iniciativa, sanção, veto e leis delegadas. Os arts.112 a 116 iniciam a disciplina de fiscalização contábil, financeira e orçamentária. Leia cada inciso no texto oficial vinculado: este roteiro organiza o estudo, mas não reproduz integralmente todos os dispositivos.</p>'),
      S('Controle interno, constitucionalidade e artigos especiais','<p>O art.121 prevê sistema integrado de controle interno dos três Poderes, com avaliação de metas do PPA, execução orçamentária, legalidade, eficácia e eficiência, controle de operações de crédito e apoio ao controle externo. Quem responde pelo controle interno deve comunicar irregularidades ao TCE, sob pena de responsabilidade solidária. Cidadão, partido, associação ou sindicato podem denunciar, na forma da lei.</p><p>O art.161 inclui competências do TJ, como mandado de segurança contra atos da Mesa ou do Presidente da Assembleia e ADI estadual contra lei ou ato normativo estadual ou municipal diante da Constituição estadual. O art.162 enumera legitimados: Governador, Mesa da ALEPA, PGJ, Defensor Público-Geral, OAB seccional, partido representado na Assembleia e entidades indicadas; para normas municipais, há legitimados adicionais nas condições do inciso VIII. Não copie mecanicamente o rol federal. A declaração de inconstitucionalidade pelo TJ exige maioria absoluta.</p><p>O art.168, atualizado pela EC101/2026 no documento oficial, dispõe sobre a Justiça Militar estadual: primeiro grau com juízes de Direito e Conselhos de Justiça Militar; segundo grau com o TJ. O art.341 determina comissão de transição governamental em até quinze dias úteis da proclamação do resultado eleitoral estadual ou municipal, com publicidade, organização de documentos e regras de composição em lei. Estes dois dispositivos não tratam de organização da Mesa: a numeração merece atenção.</p>')
    ],[
      ['A legislatura prevista no art.86 dura:','Quatro anos','Um ano','Dois meses','Seis anos','Oito anos','A legislatura acompanha o mandato parlamentar de quatro anos; sessão legislativa é conceito distinto.'],
      ['A autonomia financeira da ALEPA:','Convive com limites da LDO para sua proposta','Permite ignorar o orçamento','Elimina prestação de contas','Subordina o Plenário a fornecedor','Dispensa aprovação interna','O art.86 prevê limites estipulados na LDO e aprovação da proposta pelo Plenário antes do encaminhamento pelo Presidente.'],
      ['Segundo o art.90, a representação judicial do Legislativo cabe:','À Procuradoria da Assembleia, nos termos constitucionais','A qualquer servidor sem habilitação','Exclusivamente à Mesa de uma Câmara Municipal','Sempre ao governador pessoalmente','À comissão eleitoral','O dispositivo prevê Procuradoria da Assembleia, sem prejuízo das atribuições da PGE.'],
      ['Uma CPI tem como requisito constitucional de investigação:','Fato determinado e prazo certo','Objeto ilimitado e duração eterna','Poder de condenação criminal','Dispensa de regras constitucionais','Substituição de todos os tribunais','CPI investiga, respeitando limites e garantias; não julga crimes como tribunal.'],
      ['O controle interno previsto no art.121 deve:','Apoiar o controle externo','Substituir permanentemente o TCE','Ocultar irregularidades','Atuar só no Executivo','Excluir avaliação de resultados','Apoio ao controle externo é finalidade expressa do sistema integrado dos Poderes.'],
      ['O responsável pelo controle interno que conhece irregularidade deve:','Dar ciência ao TCE, sob pena de responsabilidade solidária','Aguardar sempre ordem do investigado','Destruir os documentos','Comunicar apenas a particulares','Divulgar senhas da instituição','O dever de ciência ao TCE está expresso no art.121, §1º. Não se confunde com divulgação indiscriminada de dados.'],
      ['A ADI estadual de lei municipal diante da Constituição do Pará é julgada:','Pelo Tribunal de Justiça, na competência constitucional','Sempre pela própria prefeitura','Exclusivamente por comissão de vereadores','Pelo governador sem processo','Por votação popular informal','O art.161, I, l, atribui a competência ao TJ. O parâmetro indicado é a Constituição estadual.'],
      ['Para a declaração de inconstitucionalidade pelo TJ, o art.162 exige:','Maioria absoluta de seus membros','Um único voto','Maioria dos cidadãos','Unanimidade de deputados','Decisão do Presidente da ALEPA','O §5º estabelece maioria absoluta, alinhada à reserva de plenário.'],
      ['No art.168 atualizado pela EC101/2026, o segundo grau da Justiça Militar estadual é exercido:','Pelo Tribunal de Justiça do Estado','Pela Mesa da ALEPA','Pelo TCE','Por empresa contratada','Pela Câmara dos Deputados','A redação oficial consultada atribui o segundo grau ao TJ. Não se deve usar redação antiga sem conferir a alteração.'],
      ['A comissão de transição do art.341 deve ser instituída em até:','Quinze dias úteis após a proclamação do resultado','Trinta anos após a eleição','Um dia antes da candidatura','Noventa dias corridos após a posse','Dois anos após a diplomação','O marco é a proclamação do resultado e o prazo é de quinze dias úteis; trocar marco ou natureza dos dias altera a regra.']
    ],[PA,RI],[VIDEO]),
    L('leg-regimento','Regimento da ALEPA e tramitação legislativa','Mesa, Presidência, Plenário, sessões, comissões, CCJ e CCFO; proposições, emendas, quóruns, turnos, interstícios, urgência, prioridade, preferência, destaque, prejudicialidade, discussão, votação, autógrafos, sanção, veto, promulgação, publicação e assessoramento.',[
      S('Quem faz o quê','<p>O Regimento oficial consultado foi aprovado pela Resolução 02/2022. A Mesa é órgão colegiado de direção; a Presidência tem atribuições próprias de representação e condução dos trabalhos; o Plenário reúne os deputados para deliberação. Não atribua à Presidência toda competência que pertence à Mesa ou ao Plenário. Sessões deliberativas ordinárias e extraordinárias destinam-se à apreciação de matérias; sessões solenes e especiais possuem finalidade própria. Ordem do Dia é a fase de apreciação da pauta, distinta dos expedientes e pronunciamentos.</p><p>Comissões permanentes examinam matérias segundo competência temática e exercem fiscalização; temporárias atendem objetivo específico. Relator prepara manifestação, mas parecer da comissão depende de sua apreciação colegiada. A CCJ examina aspectos constitucionais, jurídicos e de técnica legislativa, inclusive redação final nos termos regimentais. A CCFO examina matéria financeira e orçamentária. Assessoria técnica orienta e fundamenta; não substitui o voto do parlamentar.</p>'),
      S('Proposições e percurso','<p>Proposição é gênero: abrange propostas de emenda à Constituição, projetos, requerimentos, emendas, moções, indicações e pareceres nas condições regimentais. Projeto de lei veicula disciplina sujeita ao processo de formação da lei; decreto legislativo e resolução servem às matérias próprias da competência legislativa sem confundir-se com decreto do governador. Requerimento pede providência; indicação sugere atuação; moção expressa manifestação institucional.</p><p>Emenda altera proposição: supressiva elimina, aditiva acrescenta, modificativa muda texto, substitutiva apresenta substituição; subemenda altera emenda. Apresentação e recebimento antecedem distribuição às comissões competentes. Seguem instrução, parecer, pauta, discussão, votação e redação final, com variações regimentais e matérias especiais. Autógrafo documenta o texto aprovado para encaminhamento. Turno é etapa deliberativa; interstício é intervalo exigido entre atos. Urgência e prioridade alteram o curso nos limites previstos, sem dispensar requisitos constitucionais.</p>'),
      S('Deliberação e conclusão do processo','<p>Quórum de presença e quórum de aprovação são distintos. A regra constitucional geral exige presença da maioria absoluta e decisão por maioria de votos, salvo exceções. Maioria absoluta calcula-se sobre o total de membros; maioria simples refere-se aos votos na deliberação regular. Em Casa hipotética com 41 membros, maioria absoluta é 21, mesmo se apenas 25 comparecerem. Emenda constitucional tem procedimento e maioria qualificada próprios; lei complementar exige maioria absoluta. Consulte os artigos específicos para os turnos e prazos, sem transportar regras do Congresso automaticamente.</p><p>Preferência muda a precedência; destaque separa parte para apreciação; prejudicialidade impede prosseguir na apreciação de matéria que perdeu objeto ou ficou incompatível com deliberação anterior. Discussão não é votação. Redação final deve refletir o aprovado e não criar decisão substantiva nova.</p><p>Sanção é concordância do Executivo com projeto de lei. Veto é discordância por inconstitucionalidade ou contrariedade ao interesse público e admite apreciação legislativa. Veto parcial não pode recortar palavras para criar sentido diferente: observa unidades normativas integrais previstas constitucionalmente. Promulgação atesta a existência da lei; publicação divulga oficialmente; vigência indica quando começa a obrigar. Esses momentos não são sinônimos. Emendas à Constituição, decretos legislativos e resoluções não seguem sanção do governador como leis ordinárias.</p>')
    ],[
      ['O parecer de um relator e o parecer da comissão:','Não são automaticamente a mesma coisa','Sempre dispensam votação colegiada','São sanção governamental','Substituem o texto constitucional','São ordens judiciais','O relator propõe sua conclusão, submetida à deliberação da comissão segundo o regimento.'],
      ['A CCJ examina especialmente:','Constitucionalidade e aspectos jurídicos e de redação','Somente contratação de computadores','Apenas folha salarial','Exclusivamente apuração criminal','Só licenças médicas','A função indicada distingue a CCJ das comissões temáticas, sem esgotar suas atribuições regimentais.'],
      ['Emenda supressiva é a que:','Elimina parte da proposição','Acrescenta sempre um capítulo','Promulga a Constituição','Julga contas','Autoriza despesas sem lei','Supressão remove texto; adição acrescenta e modificação altera.'],
      ['Subemenda altera:','Uma emenda','Uma sentença judicial','A composição do eleitorado','O resultado eleitoral','Um contrato privado necessariamente','Subemenda tem por objeto outra emenda, respeitados os limites regimentais.'],
      ['Maioria absoluta de uma Casa hipotética com 41 membros corresponde a:','21 membros','20 membros','Metade dos presentes em qualquer caso','41 membros sempre','11 membros','Maioria absoluta é o primeiro inteiro superior à metade do total: 20,5 leva a 21.'],
      ['Interstício é:','Intervalo entre atos ou etapas exigido pela norma','Uma espécie de tributo','Sanção tácita','Parecer judicial','Emenda supressiva','O intervalo é distinto de turno, que é etapa deliberativa.'],
      ['Destaque permite, nas condições regimentais:','Apreciar separadamente parte da matéria','Dispensar a Constituição','Revogar qualquer decisão judicial','Substituir a iniciativa popular','Encerrar a legislatura','O destaque separa ponto para deliberação própria; não cria competência ilimitada.'],
      ['A urgência:','Modifica o rito dentro dos limites normativos','Elimina todo quórum constitucional','Transforma projeto em lei sem voto','Dispensa qualquer publicidade','Torna a Mesa tribunal penal','Aceleração processual não afasta a Constituição nem todos os atos essenciais.'],
      ['Autógrafo é:','Texto formalmente aprovado para o encaminhamento pertinente','Veto oral do governador','Opinião informal de servidor','Lista de eleitores','Sinônimo de lei sempre vigente','Autógrafo registra o aprovado; ainda pode haver sanção, veto e outras fases para projetos de lei.'],
      ['Promulgação e publicação:','São atos distintos na formação e divulgação da norma','São sempre sinônimos de sanção','Equivalem ao primeiro parecer','Dispensam aprovação parlamentar','São nomes de tipos de emenda','Promulgação atesta a existência da lei, publicação a torna oficialmente conhecida. Vigência é outra questão.']
    ],[RI,PA],[VIDEO]),
    L('leg-orcamento','Fiscalização, orçamento e participação popular','Fiscalização e controle; prestação de contas; PPA, LDO e LOA; projetos e emendas orçamentárias; CCFO; matérias especiais e iniciativa popular.',[
      S('Planejar, orientar, autorizar','<p>O <strong>PPA</strong> estabelece planejamento de médio prazo com diretrizes, objetivos e metas. A <strong>LDO</strong> orienta a elaboração do orçamento anual e conecta plano e orçamento. A <strong>LOA</strong> estima receitas e fixa despesas para o exercício. Esses instrumentos não são intercambiáveis: uma previsão genérica no PPA não substitui dotação orçamentária, e uma dotação na LOA não dispensa os demais requisitos de execução.</p><p>Projetos orçamentários têm iniciativa do Executivo e rito especial, com exame pela comissão competente, debate e deliberação legislativa. A ALEPA participa por votação, emendas nos limites constitucionais e fiscalização. A CCFO analisa matéria financeira e orçamentária, incluindo compatibilidade e repercussões das propostas. Datas e procedimentos do orçamento estadual devem ser conferidos na Constituição e no Regimento do Pará; não se deduzem automaticamente dos prazos federais.</p>'),
      S('Emendas e controle','<p>Emendas orçamentárias devem respeitar os requisitos de compatibilidade com PPA e LDO, indicação de recursos quando exigida e vedações constitucionais. Não basta desejar uma nova despesa: a proposta precisa atender às regras materiais e processuais. Remanejar recursos não pode violar indiscriminadamente dotações protegidas. Distingua aprovação da programação, execução, empenho, liquidação e pagamento; uma despesa autorizada pode depender de outras condições para ser realizada.</p><p>Fiscalização contábil, financeira, orçamentária, operacional e patrimonial observa legalidade, legitimidade e economicidade. Legalidade pergunta se houve respeito à norma; economicidade examina custo adequado; avaliação operacional considera funcionamento e resultados. Controle externo é exercido pelo Legislativo com auxílio do Tribunal de Contas, que tem competências constitucionais próprias e não é simples departamento subordinado da Assembleia. Controle interno integra cada Poder e deve apoiar o externo.</p>'),
      S('Contas e iniciativa popular','<p>Não confunda apreciação de contas de governo, com parecer prévio do Tribunal de Contas e julgamento político competente, com julgamento de contas de administradores nas hipóteses atribuídas ao Tribunal. Prestação de contas permite verificar como recursos foram empregados; quem administra recursos públicos não pode ocultar documentos por simples conveniência. Transparência precisa conviver com proteção de dados pessoais e sigilos legais.</p><p>A iniciativa popular permite apresentação de proposição mediante os requisitos constitucionais e regimentais. Não equivale à aprovação automática, nem afasta a competência legislativa e as reservas de iniciativa. A ALEPA disponibiliza formulário oficial de adesão. Audiências públicas, petições, ouvidoria e acesso à informação ampliam a participação, mas cada instrumento possui efeito próprio. No sistema legislativo digital, rastreabilidade de assinaturas, versões, pareceres, votação e publicação ajuda tanto a participação quanto a fiscalização.</p>')
    ],[
      ['Qual instrumento estima receitas e fixa despesas anuais?','LOA','PPA exclusivamente','Regimento de pessoal','Código Civil','Ata de comissão','A LOA corresponde ao orçamento anual. PPA planeja médio prazo e LDO orienta a elaboração do orçamento.'],
      ['A LDO funciona como:','Orientação para o orçamento anual em conexão com o planejamento','Substituto de todo contrato','Documento sem função orçamentária','Sentença sobre improbidade','Autorização genérica para qualquer gasto','A LDO liga prioridades e diretrizes à elaboração da LOA, além de seus demais conteúdos legais.'],
      ['Uma previsão no PPA:','Não substitui automaticamente dotação e requisitos de execução','Autoriza pagamento imediato de qualquer valor','Dispensa a LOA','Revoga a LDO','Elimina licitação em todos os casos','Planejamento e autorização orçamentária são etapas distintas; execução também exige observância das regras aplicáveis.'],
      ['A comissão especialmente ligada ao exame financeiro e orçamentário na ALEPA é:','CCFO','Um júri popular','Conselho de Justiça Militar','Tribunal eleitoral','Somente comissão de festas','A CCFO possui competência temática para fiscalização financeira e orçamentária.'],
      ['Controle externo é exercido:','Pelo Legislativo com auxílio do Tribunal de Contas','Somente pelo fornecedor','Exclusivamente pela ouvidoria','Apenas pelo gestor fiscalizado','Por empresa de auditoria sem competência pública','O Tribunal possui competências próprias e auxilia o controle externo constitucionalmente atribuído ao Legislativo.'],
      ['Avaliar se uma aquisição teve custo adequado está relacionado a:','Economicidade','Imunidade parlamentar','Subemenda','Sanção tácita','Iniciativa reservada','Economicidade examina uso racional e adequado dos recursos. Não se confunde com institutos de tramitação.'],
      ['Uma emenda ao orçamento:','Deve atender aos limites materiais e processuais aplicáveis','Pode criar qualquer gasto sem recursos','Dispensa compatibilidade com o planejamento','Nunca é analisada pelo Legislativo','Tem sempre natureza de sentença','O poder de emendar não é ilimitado; compatibilidade e requisitos constitucionais condicionam a proposta.'],
      ['Parecer prévio sobre contas e julgamento de contas:','São funções distintas conforme a espécie de conta e a competência','São sempre o mesmo ato','Nunca envolvem o Legislativo','São atos privados de contratado','Dispensam documentação','A prova pode trocar contas de governo e contas de administradores. Identificar natureza e autoridade competente é essencial.'],
      ['Iniciativa popular significa:','Apresentação de proposta sob requisitos legais, sujeita à tramitação','Aprovação automática da lei','Sanção pelos eleitores','Dispensa de competência legislativa','Revogação das reservas de iniciativa','Participação inicia o processo nas condições previstas; não elimina análise, deliberação e limites constitucionais.'],
      ['Um sistema de orçamento com histórico de alterações favorece:','Rastreabilidade e controle','Ocultação de autoria','Dispensa de auditoria','Exclusão do controle externo','Irresponsabilidade do gestor','Histórico permite reconstruir decisões e examinar sua regularidade. Tecnologia apoia, sem substituir, os controles institucionais.']
    ],[RI,PA,{title:'Constituição Federal — arts.165 a 169',url:'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'}],[VIDEO]),
    L('leg-tecnica','Técnica legislativa e catálogo dos atos do edital','LC federal 95/1998 e alterações; decretos legislativos e resoluções expressamente enumerados no Anexo II.',[
      S('Estrutura e redação conforme a LC95','<p>A lei possui parte preliminar (identificação, ementa, preâmbulo, objeto e âmbito), parte normativa (comandos substantivos) e parte final (implementação, disposições transitórias, vigência e revogação, quando cabíveis). Ementa resume o objeto; epígrafe identifica a espécie, o número e o ano. O primeiro artigo deve delimitar o objeto e o âmbito de aplicação. Salvo codificações, cada lei deve tratar de um objeto, sem matéria estranha ou sem conexão pertinente.</p><p>O artigo é a unidade básica. Artigos se desdobram em parágrafos ou incisos; parágrafos em incisos; incisos em alíneas; alíneas em itens. Numeração ordinal vai até o nono; a partir do décimo, cardinal. Incisos usam algarismos romanos, alíneas letras minúsculas e itens algarismos arábicos. Parágrafo complementa ou excepciona o comando do caput; enumerações devem usar a estrutura adequada.</p><p>Clareza pede frases diretas e concisas; precisão evita ambiguidade; ordem lógica reúne matérias relacionadas. Repetir o mesmo termo para o mesmo conceito é desejável na lei: sinônimos meramente estilísticos podem criar dúvida interpretativa. Remissões devem indicar expressamente o dispositivo, em lugar de referências vagas como artigo anterior.</p>'),
      S('Vigência, alteração e consolidação','<p>A vigência deve ser expressa e prever prazo razoável de conhecimento; entrada em vigor na publicação é reservada às leis de pequena repercussão. Na vacância, incluem-se a data de publicação e o último dia do prazo, e a entrada em vigor ocorre no dia seguinte à consumação. A cláusula revogatória enumera expressamente normas ou dispositivos revogados.</p><p>Na alteração, evite renumerar artigos: acréscimos usam o número anterior acompanhado de letras. Não reaproveite número de dispositivo revogado ou vetado. A marca NR identifica a nova redação segundo a técnica legal. Consolidação integra normas pertinentes preservando alcance e força normativa; não é oportunidade de inovar disfarçadamente. As regras da LC95, o processo constitucional e o Regimento se complementam: redação tecnicamente boa não corrige falta de competência ou vício de iniciativa.</p>'),
      S('Atos locais: lista integral exigida no anexo','<p><strong>Decretos Legislativos:</strong> 70/1990; 39/1991; 32 e 53/1993; 29/1995; 06, 14, 36 e 41/1997; 04/2000; 22/2003; 01/2006; 01, 04 e 10/2007; 04/2008; 45/2009; 06/2010; 03, 04 e 106/2012; 18/2013; 27/2014; 05 e 35/2015; 02 e 11/2017; 111/2020; 15 e 36/2021; 02 e 23/2022; 05/2023; 13 e 14/2024; 11, 12 e 13/2025.</p><p><strong>Resoluções:</strong> 11, 13, 18 e 62/1991; 14/1992; 02, 04, 05, 18 e 29/1993; 04/1995; 11/1997; 01/1999; 03/2007; 04 e 08/2012; 03/2013; 01 e 05/2017; 04/2019; 02, 03 e 04/2021; 02/2023; 01 e 02/2025; 18/1989.</p><p><strong>Validação pendente:</strong> a lista acima preserva o escopo do PDF do usuário. O teor, a vigência e as alterações de cada um desses atos não foram individualmente confirmados nesta edição; portanto, este bloco é um catálogo de leitura obrigatória, e não uma aula completa sobre o conteúdo de cada ato. Consulte cada número e ano no Banco de Leis e no Diário Oficial da ALEPA. Não presuma que todos alteram o Regimento ou que estão integralmente vigentes. O Regimento oficial localizado é aprovado pela Resolução 02/2022, que deve ser distinguida dos atos 02/2021, 02/2023 e 02/2025 da lista.</p>')
    ],[
      ['A unidade básica de articulação da lei é:','Artigo','Ementa','Livro obrigatoriamente','Preâmbulo','Epígrafe','A LC95 define artigo como unidade básica. Ementa e epígrafe pertencem à identificação e apresentação.'],
      ['A ementa deve:','Explicitar concisamente o objeto da lei','Reproduzir todos os artigos','Listar votos dos parlamentares','Substituir a sanção','Ser uma justificativa extensa','A ementa apresenta o objeto sob forma concisa de título; não equivale à justificativa nem ao corpo normativo.'],
      ['Os incisos são representados por:','Algarismos romanos','Letras gregas','Somente letras maiúsculas','Asteriscos obrigatórios','Números escritos por extenso sempre','Incisos usam romanos; alíneas, letras minúsculas; itens, arábicos.'],
      ['Uma alínea pode desdobrar-se em:','Itens','Constituições','Livros obrigatoriamente','Preâmbulos','Ementas','A sequência de articulação prevê incisos em alíneas e alíneas em itens.'],
      ['O parágrafo costuma expressar:','Complementos ou exceções à norma do caput','Tema sem relação com o artigo','Somente nomes de autores','Votos divergentes','Objeto de uma lei estrangeira','Ordem lógica exige vínculo do parágrafo com a norma principal do artigo.'],
      ['Para precisão normativa, é adequado:','Usar o mesmo termo quando repetir o mesmo conceito','Alternar sinônimos apenas por estilo','Empregar palavras ambíguas','Remeter sempre ao dispositivo anterior sem número','Usar metáforas extensas','Uniformidade terminológica reduz dúvidas sobre mudança de significado. Linguagem jurídica não deve variar só por ornamentação.'],
      ['A cláusula de revogação deve:','Enumerar expressamente as normas ou dispositivos revogados','Limitar-se sempre a revogam-se disposições contrárias','Ser omitida quando houver revogação expressa','Revogar qualquer norma sem identificação','Indicar só o autor do projeto','A LC95 exige enumeração expressa; fórmulas genéricas não atendem à técnica prevista.'],
      ['Ao inserir artigo entre dispositivos existentes, deve-se em regra:','Usar o número anterior acrescido de letras','Renumerar todos os artigos seguintes','Reaproveitar número revogado','Eliminar referências anteriores','Alterar o número da Constituição','A técnica evita renumeração e preserva referências. A LC95 disciplina o acréscimo com letras.'],
      ['A consolidação legislativa deve:','Preservar o alcance normativo das disposições consolidadas','Criar livremente novas obrigações ocultas','Dispensar identificação de fontes','Alterar competência constitucional','Substituir o processo legislativo por decisão privada','Consolidar organiza e integra normas sem inovação de alcance; alterações admitidas têm limites e justificativas.'],
      ['Encontrar o número de um ato no edital permite concluir que:','Seu conteúdo e vigência ainda precisam ser consultados na fonte oficial','Todo ato altera o Regimento','Todos têm conteúdo idêntico','Todos permanecem integralmente vigentes','A numeração dispensa o ano','Número e ano identificam a norma, mas não demonstram seu teor nem suas alterações. O catálogo não substitui a leitura.']
    ],[{title:'LC95/1998 — texto oficial e alterações',url:'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp95.htm'},LEIS,RI],[VIDEO])
  ];
})();

window.LEGISLACAO.forEach(aula => aula.sections.unshift({title:'Recorte normativo do concurso',body:'<p>O edital de abertura, itens 11.8 e 11.8.1, considera a legislação com vigência anterior à publicação de 28/09/2026 e exclui alterações posteriores. Textos oficiais mantidos na internet podem receber novas alterações: use o recorte do edital. A Retificação 002, de 01/10/2026, corrige o programa e deve ser observada.</p><p><a href="https://anexos-r2.selecao.net.br/uploads/237/concursos/156/anexos/8997e283-4a70-47a1-92d0-393d59711e32.pdf" target="_blank" rel="noopener">Edital de abertura</a> · <a href="https://anexos-r2.selecao.net.br/uploads/237/concursos/156/anexos/87d439ce-eac5-4a39-9ce3-61e48ed2eccb.pdf" target="_blank" rel="noopener">Retificação 002</a></p>'}));
window.LEGISLACAO.find(a=>a.id==='leg-tecnica').sections.find(s=>s.title==='Atos locais: lista integral exigida no anexo').body = window.LEGISLACAO.find(a=>a.id==='leg-tecnica').sections.find(s=>s.title==='Atos locais: lista integral exigida no anexo').body.replace(/<strong>Validação pendente:<\/strong>[\s\S]*?Consulte cada número/, '<strong>Retificação oficial:</strong> o anexo enviado mencionava 18/2026; o Edital de Retificação 002, de 01/10/2026, página 5, corrigiu a referência para Resolução 18/1989. Os textos oficiais estão disponíveis no catálogo integrado. A consolidação de todas as alterações e a análise individual aprofundada ainda não estão completas. Consulte cada número');
